#include <vector>
#include <utility>
#include "../../../kelly-slaters-pro-surfer/KS/SRC/custom_stl.h"

class typeface_def {
public:
  struct inter_kern {
    inter_kern() {}
    inter_kern(int l1, int l2, int k) {
      letter_pair = pair<int, int>(l1, l2);
      kern = k;
    }
    pair<int, int> letter_pair;
    int kern;
  };
};

void instantiate_inter_kern_push_back(
    vector<typeface_def::inter_kern, my_allocator<typeface_def::inter_kern> >& values,
    const typeface_def::inter_kern& value) {
  values.push_back(value);
}
